-- 0295: climbs on a list the source has re-filed onto a named boulder or wall we already have, moved there.
--
-- Asked: "do the rest" (2026-10-15), after 0292 found Rainbow Mountain's catch-all list beside boulders the source
-- now names, and 0293 found two more ("Forest Hill Park Bouldering", "A and B Blocks"). Swept the whole catalog:
-- for every area, how many of its climbs the source still files under that area vs under another. 1,157 lists
-- file most of theirs elsewhere; a climb moves only when the source lists its name ONCE in the state, under an
-- area of ours that shares the list's parent or grandparent, is within 3 km, holds no climbs' sub-areas and lacks
-- the climb — and its name is not a generic one ("Project", "V0", "Traverse"). 40 drawn at random were checked
-- against the source's live pages: all 40 agree.
--   Typical: Stone Fort's 356-problem list beside 60 named boulders (each with a few of its problems); T-Wall East,
--   which the source now files as Orange Blossom Wall and The Amphitheater; Cactus Cliff's list beside its four
--   sections; the Gunks' "Moe (closure) to Harvest Moon", an older copy of "Closure to Harvest Moon".
-- A list every climb leaves goes: into the one area it copied (50), or into its crag (12).
-- Left in place, read: climbs whose source home we do not have (an area to create), names the source lists more
-- than once in the state, and generic names.
-- 3 climbs merged (1 take a grade), 4174 moved, 62 areas deleted.
-- No contribution, log, photo, topo, list or report on any climb this deletes; a moved climb keeps its id.
-- ABORTS if climber data points at a climb deleted, or if the live tree no longer matches the plan.
-- Plan: the job's fold16/ (sweep.mjs, classify.mjs, filter.mjs, decide.mjs); rollback: scripts/data/catch-alls-rollback.json.

begin;

create temp table m_merge(keep text not null, drop_id text primary key, grade text, grade_num numeric, disc text) on commit drop;
insert into m_merge values
